def readable(text):
 replacements={'At330':'At update 330','at330':'at update 330','at100':'at update 100','at170':'at update 170','at80':'at update 80','at120':'at update 120','state0':'state 0','andlearning':'and learning','medianCE':'median CE','MeanCE':'Mean CE','baselineCE':'baseline CE','20-probe':'20-probe','seed,20':'seed, 20','andall':'and all','All80':'All 80','all80':'all 80','All20':'All 20','all20':'all 20','allfour':'all four','allstates':'all states','allseven':'all seven','allscales':'all scales','andall':'and all','exact20':'exact 20','independent8':'independent 8','original7':'original 7','mean7':'mean 7','andmedian':'and median','then20':'then 20','bootstrapped10':'bootstrapped 10','RNG20260925':'RNG 20260925','is20':'is 20','not400':'not 400','on26':'on 26','versus14':'versus 14','despite20':'despite 20','from13':'from 13','to25':'to 25','and26':'and 26','only4':'only 4','the12':'the 12','allpreviously':'all previously','twoNI':'two NI','ranges.05':'ranges .05','ranges0':'ranges 0','median.':'median .','in19':'in 19','and20':'and 20','are71':'are 71','and65':'and 65','the25':'the 25','allwithin':'all within','Allwithin':'All within','andcontext':'and context','andearly':'and early','AllCE':'All CE','andcommon':'and common','andclass':'and class','andcontrast':'and contrast','orbetter':'or better','andA/B':'and A/B','is19':'is 19','atinitialization':'at initialization','and19':'and 19','from.9':'from .9','to1.358':'to 1.358','by1.182757':'by 1.182757','allfour':'all four','andsigned':'and signed','gives94':'gives 94','primaryα':'primary α','gives26':'gives 26','only6':'only 6','andnonzero':'and nonzero','NI415':'NI 415','andNC423':'and NC 423','andunassessed':'and unassessed','fullhuman':'full human','all480':'all 480','maxlogit':'maximum logit','maxprobability':'maximum probability','Allwithin':'All within','67,200':'67,200','||':'‖'}
 for a,b in replacements.items():text=text.replace(a,b)
 text=re.sub(r',(?=[A-Za-zα])',', ',text);text=re.sub(r';(?=[A-Za-zα])','; ',text)
